var SC=window.SugarCube; var p=SC.State.variables.player; p.core_traits=p.core_traits||{}; p.core_traits.corruption=0;
SC.Engine.play("Canvas_frank_kitchen_morning_hub_Node_1");
var pas=document.querySelector(".passage")||document.body;
return JSON.stringify({
 locked: [].map.call(pas.querySelectorAll("span.locked-choice"), s=>s.textContent.trim()),
 clickable: [].map.call(pas.querySelectorAll("a.link-internal, a[data-passage]"), a=>a.textContent.trim()).filter(t=>t),
 yellow: [].map.call(pas.querySelectorAll("span.unlocked-choice"), s=>s.textContent.trim())
