var SC=window.SugarCube; var p=SC.State.variables.player; p.core_traits.corruption=30;
SC.Engine.play("Canvas_frank_kitchen_morning_hub_Node_1");
var pas=document.querySelector(".passage")||document.body;
return JSON.stringify({
 corr: p.core_traits.corruption,
 locked: [].map.call(pas.querySelectorAll("span.locked-choice"), s=>s.textContent.trim()),
 clickable: [].map.call(pas.querySelectorAll("a.link-internal, a[data-passage]"), a=>a.textContent.trim()).filter(t=>t),
 yellow_unlocked: [].map.call(pas.querySelectorAll("span.unlocked-choice"), s=>s.textContent.trim())
});

var SC=window.SugarCube; var setup=SC.setup; var p=SC.State.variables.player;
function probe(c){ p.core_traits.corruption=c;
  return { corr:c,
    kitchen_hub_hasNewUnlocked: setup.canvasHasNewUnlockedChoices("frank_kitchen_morning_hub"),
    livingroom_hub_hasNewUnlocked: setup.canvasHasNewUnlockedChoices("frank_living_room_hub"),
    yard_hub_hasNewUnlocked: setup.canvasHasNewUnlockedChoices("frank_yard_hub") }; }
return JSON.stringify({ at_corr0: probe(0), at_corr30: probe(30) });

var SC=window.SugarCube; var setup=SC.setup; var p=SC.State.variables.player;
var cc = (setup.help_data||{}).canvasConditionalChoices||{};
// find the kitchen morning hub UUID by scanning canvas registry
var idMap = setup._canvasByIdMap||{};
var hubUuid=null;
for (var k in idMap){ if((idMap[k].name||"")==="Kitchen — Frank, morning"){ hubUuid=k; break; } }
function probe(c){ p.core_traits.corruption=c;
  return { corr:c,
    hub_uuid: hubUuid,
    cc_entries: (cc[hubUuid]||[]).length,
    hasNewUnlocked_byUuid: setup.canvasHasNewUnlockedChoices(hubUuid),
    isCanvasNew: setup.isCanvasNew(hubUuid) }; }
return JSON.stringify({ corr0: probe(0), corr30: probe(30) });

var SC=window.SugarCube; var p=SC.State.variables.player; p.core_traits.corruption=0;
SC.Engine.play("Location_Kitchen");
var d=document;
var portraits=[].map.call(d.querySelectorAll(".npc-portrait-card"), function(c){
  return { cls:c.className,
           name:(c.querySelector(".npc-portrait-name")||{}).textContent,
           badges:[].map.call(c.querySelectorAll(".npc-badge"), b=>b.textContent.trim()) };
});
var navNew=[].map.call(d.querySelectorAll(".nav-new-badge"), e=>e.textContent.trim());
var navUnlocked=[].map.call(d.querySelectorAll(".nav-unlocked-badge"), e=>e.textContent.trim());
return JSON.stringify({passage:SC.State.passage, portraits:portraits, nav_new_badges:navNew, nav_unlocked_badges:navUnlocked});

var SC=window.SugarCube; var setup=SC.setup; var p=SC.State.variables.player;
function look(c){ p.core_traits.corruption=c;
  var html=""; try{ html=setup.renderNpcPortraits("loc_kitchen")||""; }catch(e){ html="ERR:"+e.message; }
  return { corr:c,
    has_new_border: /npc-portrait-new/.test(html),
    has_unlocked_green_border: /npc-portrait-unlocked/.test(html),
    has_NEW_badge: /npc-badge-new/.test(html),
    has_unlock_badge: /npc-badge-unlocked/.test(html),
    frank_present: /Frank/.test(html),
    len: html.length }; }
return JSON.stringify({ corr0: look(0), corr30: look(30) }, null, 1);

var SC=window.SugarCube; var setup=SC.setup; var p=SC.State.variables.player;
var cc=(setup.help_data||{}).canvasConditionalChoices||{};
var idMap=setup._canvasByIdMap||{};
function nameOf(u){ return (idMap[u]&&idMap[u].name)||"?"; }
function scan(c){ p.core_traits.corruption=c; var hits=[];
  for (var u in cc){ if(setup.canvasHasNewUnlockedChoices(u)) hits.push(nameOf(u)); }
  return {corr:c, canvases_flagged_new_unlocked: hits}; }
return JSON.stringify({ total_conditional_canvases:Object.keys(cc).length, at_corr0:scan(0), at_corr30:scan(30) }, null, 1);

var SC=window.SugarCube; var setup=SC.setup; var p=SC.State.variables.player; p.core_traits.corruption=0;
var cc=(setup.help_data||{}).canvasConditionalChoices||{};
var out=[];
for (var u in cc){
  var choices=cc[u]; var flagged=setup.canvasHasNewUnlockedChoices(u);
  if(!flagged) continue;
  out.push({ uuid:u, n_choices:choices.length,
    conds: choices.map(function(ch){ return JSON.stringify(ch.conditions && ch.conditions.items); }),
    satisfiedAtCorr0: choices.map(function(ch){ return setup.triggerConditionsSatisfied(ch.conditions); }) });
}
return JSON.stringify(out, null, 1);
